import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736";
const BASE_URL = "https://api.themoviedb.org/3";

export const searchMovieIdFromTMDB = async (movieTitle, openDate) => {
  try {
    const response = await axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: movieTitle,
        language: "ko-KR",
        region: "KR",
        primary_release_year: openDate?.slice(0, 4),
      },
    });

    const results = response.data.results;
    if (results.length === 0) return null;

    // 개봉일 정밀 매칭 우선
    let matched = results.find((m) => m.release_date === openDate);
    if (!matched && openDate) {
      matched = results.find((m) =>
        m.release_date?.startsWith(openDate.slice(0, 4))
      );
    }

    const target = matched || results[0];

    // 개봉일 차이 1년 이상이면 무시
    if (
      openDate &&
      target?.release_date &&
      Math.abs(new Date(openDate) - new Date(target.release_date)) >
        1000 * 60 * 60 * 24 * 365
    ) {
      return null;
    }

    return target.id;
  } catch (error) {
    console.error("TMDB movieId 검색 실패:", error);
    return null;
  }
};

// 🖼️ TMDB movieId로 포스터 URL 반환 (poster_path → fallback: backdrop_path)
export const getMoviePosterById = async (movieId) => {
  try {
    const response = await axios.get(`${BASE_URL}/movie/${movieId}`, {
      params: {
        api_key: TMDB_API_KEY,
        language: "ko-KR",
      },
    });

    const movie = response.data;
    return movie.poster_path
      ? `https://image.tmdb.org/t/p/w500${movie.poster_path}`
      : movie.backdrop_path
      ? `https://image.tmdb.org/t/p/w500${movie.backdrop_path}`
      : null;
  } catch (error) {
    console.error("TMDB 포스터 조회 실패:", error);
    return null;
  }
};

// 🎯 제목 + 개봉일 기반 포스터 전체 조회 흐름
export const getPosterFromTMDB = async (movieTitle, openDate) => {
  const movieId = await searchMovieIdFromTMDB(movieTitle, openDate);
  if (!movieId) return null;
  return await getMoviePosterById(movieId);
};
